const {esc,api,toast,modalWide,closeModal}=window;
function c04runRows(runs){if(!runs.length)return '<div class="empty">尚无 AI 执行记录。</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>时间</th><th>任务</th><th>Provider / Model</th><th>状态</th><th>耗时</th><th>隐私</th><th>Hash</th></tr></thead><tbody>${runs.map(x=>{let safety={};try{safety=JSON.parse(x.input_safety_meta_json||'{}')}catch{};const red=safety.redaction_counts||{};return `<tr><td>${esc(new Date(x.started_at).toLocaleString())}</td><td>${esc(x.task_type)}</td><td>${esc(x.provider_kind||'—')}<div class="subtle">${esc(x.model_name||'—')}</div></td><td><span class="status ${x.status==='succeeded'?'good':x.status==='failed'?'bad':'warn'}">${esc(x.status)}</span>${x.error_code?`<div class="subtle">${esc(x.error_code)}</div>`:''}</td><td>${Number(x.latency_ms||0)} ms</td><td>${safety.privacy_projection?'<span class="status good">Privacy View</span>':'<span class="status warn">未标记</span>'}<div class="subtle">${Object.entries(red).map(([k,v])=>`${esc(k)} ${v}`).join(' · ')}</div></td><td class="mono"><div>in ${esc((x.input_hash||'').slice(0,10))}</div><div>out ${esc((x.output_hash||'').slice(0,10))}</div></td></tr>`}).join('')}</tbody></table></div>`}
window.openCandidateAiRuns=async cid=>{try{const d=await api(`/api/v1/candidates/${cid}/ai-runs?limit=100`);modalWide('AI Run Ledger · 候选人',`<p class="subtle">账本只保存执行元数据、输入/输出哈希、Provider/Model、耗时与隐私投影摘要；不保存简历原文、Prompt、模型原始输出或 API Key。</p>${c04runRows(d.runs||[])}`,`<button class="btn" onclick="closeModal()">关闭</button>`)}catch(e){toast(e.message,true)}};
window.openProjectAiRuns=async pid=>{try{const d=await api(`/api/v1/projects/${pid}/ai-runs?limit=200`);modalWide('AI Run Ledger · 当前招聘项目',`<p class="subtle">用于核查 AI 实际运行、失败原因、模型版本与隐私出站状态，不等同于招聘判断。</p>${c04runRows(d.runs||[])}`,`<button class="btn" onclick="closeModal()">关闭</button>`)}catch(e){toast(e.message,true)}};
window.openDecisionHistory=async cid=>{try{const d=await api(`/api/v1/candidates/${cid}/decision-history`),rows=d.decisions||[];modalWide('人工决定 Lineage',`<p class="subtle">材料版本、招聘协议或评价策略变化会产生新的 Decision Context。历史决定不会自动成为当前决定。</p>${rows.length?`<div class="timeline">${rows.map(x=>`<div class="timeline-item"><strong>${esc(x.decision)} ${x.is_current_context?'<span class="status good">当前上下文</span>':x.stale?'<span class="status warn">历史 / stale</span>':''}</strong><small>${esc(x.actor)} · ${esc(new Date(x.created_at).toLocaleString())}</small><div>${esc(x.reason||'')}</div><div class="subtle mono">context ${esc((x.decision_context_hash||'').slice(0,16))}${x.reaffirmed_from_decision_id?` · reaffirmed from ${esc(x.reaffirmed_from_decision_id.slice(0,8))}`:''}</div></div>`).join('')}</div>`:'<div class="empty">尚无人工决定记录。</div>'}`,`<button class="btn" onclick="closeModal()">关闭</button>`)}catch(e){toast(e.message,true)}};
window.reaffirmHistoricalDecision=async cid=>{const reason=prompt('请说明为什么在当前材料与当前招聘协议下仍维持原决定：','已复核新增材料与当前标准，原决定仍成立');if(reason===null)return;if(!reason.trim()){toast('必须填写重申理由',true);return}try{const r=await api(`/api/v1/candidates/${cid}/decisions/reaffirm`,{method:'POST',body:JSON.stringify({actor:'human',reason:reason.trim()})});toast(`已在当前 Decision Context 重申：${r.decision}`);window.closeModal?.()}catch(e){toast(e.message,true)}};
